// Moving Average tests. DO NOT edit this file.
// Run with: ./run-tests.sh cpp
#include <algorithm>
#include <chrono>
#include <cmath>
#include <functional>
#include <iostream>
#include <string>
#include <vector>

#include "solution.hpp"

static const double EPS = 1e-5;

struct Failure { std::string msg; };

static void expectNear(double got, double exp, const std::string& ctx) {
    if (std::isnan(got) || std::fabs(got - exp) >= EPS)
        throw Failure{ctx + ": expected " + std::to_string(exp) + ", got " + std::to_string(got)};
}

static void check(int k, const std::vector<int>& in, const std::vector<double>& exp) {
    MovingAverage m(k);
    for (size_t i = 0; i < in.size(); ++i)
        expectNear(m.next(in[i]), exp[i],
                   "k=" + std::to_string(k) + ", call #" + std::to_string(i + 1) +
                   " next(" + std::to_string(in[i]) + ")");
}

int main() {
    std::vector<std::pair<std::string, std::function<void()>>> tests = {
        {"1. example from the problem statement", [] { check(3, {1, 10, 3, 5}, {1, 5.5, 14.0 / 3, 6}); }},
        {"2. window of size 1", [] { check(1, {4, -2, 7}, {4, -2, 7}); }},
        {"3. fewer values than the window size", [] { check(5, {2, 4}, {2, 3}); }},
        {"4. negative values", [] { check(2, {-3, -5, 10}, {-3, -4, 2.5}); }},
        {"5. window sliding several times", [] { check(2, {1, 2, 3, 4, 5}, {1, 1.5, 2.5, 3.5, 4.5}); }},
        {"6. zeros", [] { check(3, {0, 0, 0, 0}, {0, 0, 0, 0}); }},
        {"7. boundary values", [] {
            check(3, {100000, 100000, 100000, -100000}, {100000, 100000, 100000, 100000.0 / 3});
        }},
        {"8. independent instances", [] {
            MovingAverage a(2), b(3);
            expectNear(a.next(1), 1, "step #1");
            expectNear(b.next(10), 10, "step #2");
            expectNear(a.next(3), 2, "step #3");
            expectNear(b.next(20), 15, "step #4");
            expectNear(a.next(5), 4, "step #5");
            expectNear(b.next(30), 20, "step #6");
            expectNear(b.next(40), 30, "step #7");
        }},
        {"9. max constraints: k = 10^4, 10^4 calls with val = 10^5", [] {
            const int k = 10000;
            MovingAverage m(k);
            double got = 0;
            for (int i = 0; i < k; ++i) got = m.next(100000);
            expectNear(got, 100000, "after 10000 calls to next(100000)");
        }},
        {"10. stress (beyond constraints, checks O(1)): k = 100,000, 200,000 calls in under 0.5s", [] {
            const int size = 100000, n = 200000;
            std::vector<int> vals(n);
            for (int i = 0; i < n; ++i) vals[i] = (int)(((long long)i * 7919) % 200001) - 100000;
            std::vector<long long> prefix(n + 1, 0);
            for (int i = 0; i < n; ++i) prefix[i + 1] = prefix[i] + vals[i];

            MovingAverage m(size);
            std::vector<double> res(n);
            auto start = std::chrono::steady_clock::now();
            for (int i = 0; i < n; ++i) res[i] = m.next(vals[i]);
            double ms = std::chrono::duration<double, std::milli>(
                            std::chrono::steady_clock::now() - start).count();

            for (int i : {0, size - 1, size, n - 1}) {
                int lo = std::max(0, i + 1 - size);
                double exp = (double)(prefix[i + 1] - prefix[lo]) / (i + 1 - lo);
                expectNear(res[i], exp, "call #" + std::to_string(i + 1));
            }
            if (ms >= 500) throw Failure{"too slow: " + std::to_string((int)ms) + " ms (limit 500 ms)"};
        }},
    };

    int passed = 0;
    for (auto& [name, fn] : tests) {
        try {
            fn();
            std::cout << "  ✔ " << name << "\n";
            ++passed;
        } catch (const Failure& f) {
            std::cout << "  ✘ " << name << "\n      " << f.msg << "\n";
        } catch (const std::exception& e) {
            std::cout << "  ✘ " << name << "\n      exception: " << e.what() << "\n";
        }
    }
    std::cout << "\n" << passed << "/" << tests.size() << " tests passed\n";
    return passed == (int)tests.size() ? 0 : 1;
}
